const body = $json.body || $json;

if (!body.audio_base64) {
  throw new Error('WF10: audio_base64 missing');
}

const buffer = Buffer.from(
  String(body.audio_base64),
  'base64'
);

if (!buffer || buffer.length <= 44) {
  throw new Error('WF10: invalid or empty WAV');
}

let duration_seconds = 0;
let duration_unknown = true;

try {
  if (
    buffer.length >= 44 &&
    buffer.toString('ascii',0,4) === 'RIFF'
  ) {
    const byteRate = buffer.readUInt32LE(28);

    if (byteRate > 0) {
      duration_seconds = Math.round(
        Math.max(0,buffer.length - 44) / byteRate
      );
      duration_unknown = false;
    }
  }
} catch (e) {}

const filename =
  String(
    body.filename ||
    body.conversation_id ||
    body.call_job_id ||
    ('recording-' + Date.now() + '.wav')
  );

const recording_key =
  String(
    body.recording_key ||
    filename ||
    body.conversation_id ||
    body.call_job_id
  );

return [{
  json:{
    source:'PUSH',
    recording_key,

    call_job_id:
      body.call_job_id || null,

    conversation_id:
      body.conversation_id || null,

    followup_id:
      body.followup_id || null,

    provider_call_id:
      body.provider_call_id || null,

    lead_id:
      body.lead_id || null,

    route_key:
      body.route_key || null,

    country_iso:
      body.country_iso || null,

    provider:
      body.provider || null,

    adapter_key:
      body.adapter_key || null,

    phone:
      body.phone || null,

    filename,

    date:
      body.date ||
      new Date().toISOString().slice(0,10),

    duration_seconds,
    duration_unknown,

    suppress_telegram:
      body.suppress_telegram === true ||
      String(body.suppress_telegram || '')
        .toLowerCase() === 'true'
  },

  binary:{
    data:{
      data:buffer.toString('base64'),
      mimeType:'audio/wav',
      fileName:filename
    }
  }
}];

const already = new Set(
  $input.all()
    .map(i => i.json && (i.json.filename || i.json.recording_key))
    .filter(Boolean)
);

const list = await this.helpers.httpRequest({
  method:'GET',
  url:'http://172.18.0.1:8091/recordings',
  json:true
});

const recordings =
  list.recordings || [];

const today =
  new Date().toISOString().slice(0,10);

const out=[];

function wavDuration(b64,sizeBytes) {
  try {
    const head=Buffer.from(
      String(b64).slice(0,120),
      'base64'
    );

    if (head.length < 44) return null;
    if (head.toString('ascii',0,4)!=='RIFF') return null;

    const byteRate=head.readUInt32LE(28);

    if (!byteRate) return null;

    return Math.round(
      Math.max(
        0,
        Number(sizeBytes || 0) - 44
      ) / byteRate
    );

  } catch(e) {
    return null;
  }
}

for (const rec of recordings) {

  if (!rec || !rec.filename) continue;

  if (already.has(rec.filename)) {
    continue;
  }

  let date='';

  try {
    date=new Date(
      Number(rec.timestamp_ms)
    ).toISOString().slice(0,10);
  } catch(e) {}

  if (date && date !== today) {
    continue;
  }

  try {

    const dl =
      await this.helpers.httpRequest({
        method:'GET',
        url:
          'http://172.18.0.1:8091/recordings/'
          + encodeURIComponent(rec.filename),
        json:true
      });

    if (!dl.ok || !dl.audio_base64) {
      continue;
    }

    const secs =
      wavDuration(
        dl.audio_base64,
        rec.size_bytes
      );

    out.push({
      json:{
        source:'STRINGEE_WORKER',
        recording_key:String(rec.filename),

        call_job_id:
          rec.call_job_id || null,

        conversation_id:
          rec.conversation_id || null,

        followup_id:
          rec.followup_id || null,

        provider_call_id:
          rec.provider_call_id || null,

        lead_id:
          rec.lead_id || null,

        route_key:
          rec.route_key || null,

        country_iso:
          rec.country_iso || null,

        provider:
          rec.provider || 'stringee',

        adapter_key:
          rec.adapter_key || 'STRINGEE_WORKER',

        phone:
          rec.phone || null,

        filename:
          String(rec.filename),

        date:
          date || today,

        duration_seconds:
          secs === null ? 0 : secs,

        duration_unknown:
          secs === null,

        suppress_telegram:false
      },

      binary:{
        data:{
          data:String(dl.audio_base64),
          mimeType:'audio/wav',
          fileName:String(rec.filename)
        }
      }
    });

  } catch(e) {}
}

return out;

return $input.all().map(i => ({
  json:{
    skipped:true,
    recording_key:i.json.recording_key || null,
    call_job_id:i.json.call_job_id || null,
    followup_id:i.json.followup_id || null,
    reason:i.json.skip_reason || 'UNKNOWN'
  }
}));

const token=
  ($json.body || {}).accessToken ||
  $json.accessToken ||
  null;

const ctx=
  $('[CORE] Context Valid?').item;

return [{
  json:{
    ...(ctx.json || {}),
    access_token:token
  },
  binary:ctx.binary
}];

const ctx=
  $('[CRM] Attach Token + Recording').item;

const status=
  Number(
    $json.statusCode ||
    $json.status ||
    0
  );

const body=
  $json.body ||
  $json.response_body ||
  $json;

const ok=
  status >= 200 &&
  status < 300 &&
  (
    body.hasRecording === true ||
    !!body.followUpId ||
    body.ok === true
  );

return [{
  json:{
    ...(ctx.json || {}),

    crm_synced:ok,
    crm_http_status:status,

    crm_followup_id:
      body.followUpId ||
      ctx.json.followup_id ||
      null,

    crm_error:
      ok
        ? null
        : (
            body.error ||
            body.message ||
            ('HTTP_' + status)
          )
  },

  binary:ctx.binary
}];

return $input.all().map(i => ({
  json:{
    recording_key:i.json.recording_key,
    followup_id:i.json.followup_id,
    crm_synced:false,
    error:i.json.crm_error || 'CRM_UPLOAD_FAILED'
  }
}));

const src=$input.item;
const c=String(
  src.json.country_iso || ''
).toUpperCase();

/*
  Current business routing retained from working WF10.
  IMPORTANT:
  this does NOT determine the country.
  country_iso came from the V2 call job.

  Any future country not explicitly mapped falls
  to the general Telegram target automatically.
*/

const primary={
  IN:'-1004454561082',
  NP:'-1004454561082',
  MX:'-1003616406932'
};

const secondary={
  IN:'-1003984044945',
  NP:'-1003984044945',
  MX:'-1003616406932'
};

const fallback='-1003984044945';

const targets=[
  primary[c] || fallback,
  secondary[c] || fallback
];

const unique=[
  ...new Set(
    targets.filter(Boolean)
  )
];

return unique.map(chat_id => ({

  json:{
    ...src.json,
    telegram_chat_id:chat_id
  },

  binary:src.binary
}));
